insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"AWAY_GTE_5","title":"¿El visitante llega a 5 o más?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_gte","n":5},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"AWAY_GTE_6","title":"¿El visitante anota 6 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_gte","n":6},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"AWAY_GTE_7","title":"¿El visitante llega a 7 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_gte","n":7},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"AWAY_LTE_2","title":"¿El visitante se queda en 2 o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_lte","n":2},"priority":0,"cooldown":2,"tags":["defensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;